package org.slavicmyths.sanctuary;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
public final class SanctuaryHeart extends BlockEntity {
 public UUID instance;public BlockPos origin=BlockPos.ZERO;public Rotation rotation=Rotation.NONE;public boolean spring;public int pool=-1;private long ritualAt=-100;
 public SanctuaryHeart(BlockPos p,BlockState s){super(SanctuaryContent.HEART.get(),p,s);}
 public void configure(UUID id,BlockPos root,Rotation r,boolean spring,int pool){instance=id;origin=root;rotation=r;this.spring=spring;this.pool=pool;setChanged();}
 private BlockPos at(int x,int y,int z){return origin.offset(SanctuaryGeometry.rotate(x,y,z,rotation));}
 public synchronized boolean interact(Player player,InteractionHand hand){if(level==null||level.isClientSide)return true;if(!(player instanceof ServerPlayer p)||!p.isAlive()||p.isSpectator()||instance==null)return true;var w=p.serverLevel();if(!w.mayInteract(p,worldPosition)||p.server.isUnderSpawnProtection(w,worldPosition,p))return true;var d=SanctuaryRecords.get(w);d.ensure(instance,origin,rotation,spring);d.discover(p,instance);org.slavicmyths.guardians.GuardianWorld.ensure(w,instance);if(pool<0&&org.slavicmyths.guardians.GuardianWorld.ritual(p,instance))return true;var stack=p.getItemInHand(hand);
  if(!spring){if(d.restored(instance)){p.displayClientMessage(SanctuaryContent.text("already_restored"),true);return true;}if(!stack.is(SanctuaryContent.item("sacred_ember"))){p.displayClientMessage(SanctuaryContent.text("ember_needed"),true);return true;}if(!d.restore(instance))return true;stack.shrink(1);ritualAt=w.getGameTime();w.setBlockAndUpdate(worldPosition,getBlockState().setValue(SanctuaryBlock.LIT,true));SanctuaryContent.sound(w,worldPosition,"fire_restore");if(d.claim(instance,p.getUUID())){var ledger=org.slavicmyths.karachun.NightLedger.get(w);ledger.enqueue(p,new ItemStack(SanctuaryContent.item("purifying_ash")));w.getServer().overworld().getDataStorage().save();ledger.collect(p);}org.slavicmyths.item.FolkAccessoryItem.award(p,"restored_sanctuary_fire");p.sendSystemMessage(SanctuaryContent.text("fire_restored"));}
  else if(pool>=0){if((d.row(instance).getInt("Pools")&(1<<pool))!=0){p.displayClientMessage(SanctuaryContent.text("pool_clean"),true);return true;}if(!stack.is(org.slavicmyths.quest185.Quest185Content.POWDER.get())){p.displayClientMessage(SanctuaryContent.text("powder_needed"),true);return true;}if(!d.pool(instance,pool))return true;stack.shrink(1);ritualAt=w.getGameTime();w.setBlockAndUpdate(worldPosition,getBlockState().setValue(SanctuaryBlock.LIT,true));cleanPool(w);SanctuaryContent.sound(w,worldPosition,"spring_purify");org.slavicmyths.item.FolkAccessoryItem.award(p,"cleansed_sanctuary_pool");p.sendSystemMessage(SanctuaryContent.text(d.cleansed(instance)?"spring_restored":"pool_clean"));}
  else p.displayClientMessage(SanctuaryContent.text("spring_hint"),true);setChanged();return true;
 }
 public synchronized void purifyByBreaking(ServerPlayer p){if(instance==null||!spring||pool<0||pool>1)return;var d=SanctuaryRecords.get(p.serverLevel());d.ensure(instance,origin,rotation,true);if(!d.pool(instance,pool))return;d.discover(p,instance);cleanPool(p.serverLevel());SanctuaryContent.sound(p.level(),worldPosition,"spring_purify");org.slavicmyths.item.FolkAccessoryItem.award(p,"cleansed_sanctuary_pool");}
 private void cleanPool(ServerLevel w){cleanPool(w,origin,rotation,pool);}
 private static boolean cleanPool(ServerLevel w,BlockPos origin,Rotation rotation,int pool){boolean allLoaded=true;int cz=pool==0?39:48;for(int x=7;x<=24;x++)for(int z=cz-4;z<=cz+4;z++)for(int y=0;y<=3;y++){var p=origin.offset(SanctuaryGeometry.rotate(x,y,z,rotation));if(!w.hasChunkAt(p)){allLoaded=false;continue;}var s=w.getBlockState(p);if(org.slavicmyths.mor.MorBlocks.index(s)>=0)w.setBlockAndUpdate(p,org.slavicmyths.mor.MorBlocks.prototype(s));}return allLoaded;}
 public static void tick(Level level,BlockPos pos,BlockState state,SanctuaryHeart be){if(!(level instanceof ServerLevel w)||be.instance==null)return;long now=w.getGameTime();if(now%4!=0)return;var d=SanctuaryRecords.get(w);d.ensure(be.instance,be.origin,be.rotation,be.spring);var record=d.row(be.instance);if(be.pool<0&&now%20==0)org.slavicmyths.guardians.GuardianWorld.ensure(w,be.instance);if(be.spring&&record.getInt("PoolsPending")!=0&&now>=record.getLong("CleanCheckAt")){record.putLong("CleanCheckAt",now+20);int pending=record.getInt("PoolsPending");for(int index=0;index<2;index++)if((pending&(1<<index))!=0&&cleanPool(w,be.origin,be.rotation,index))pending&=~(1<<index);record.putInt("PoolsPending",pending);d.setDirty();}boolean active=be.spring?be.pool<0||(record.getInt("Pools")&(1<<be.pool))!=0:d.restored(be.instance);if(state.getValue(SanctuaryBlock.LIT)!=active)w.setBlockAndUpdate(pos,state.setValue(SanctuaryBlock.LIT,active));if(!be.spring&&active&&now%20==0)for(int[] offset:new int[][]{{-1,0},{1,0},{0,-1},{0,1}}){var p=be.at(40+offset[0],3,46+offset[1]);if(w.hasChunkAt(p)&&w.getBlockState(p).is(Blocks.CAMPFIRE)&&!w.getBlockState(p).getValue(CampfireBlock.LIT))w.setBlockAndUpdate(p,w.getBlockState(p).setValue(CampfireBlock.LIT,true));}
  if(now-be.ritualAt<40&&now%4==0){var center=be.spring?pos:be.at(40,4,46);for(int i=0;i<8;i++){double angle=i*Math.PI/4;w.sendParticles(be.spring?net.minecraft.core.particles.ParticleTypes.GLOW:net.minecraft.core.particles.ParticleTypes.FLAME,center.getX()+.5+Math.cos(angle)*1.2,center.getY()+.3,center.getZ()+.5+Math.sin(angle)*1.2,1,0,.05,0,.01);}}
  if((now/4)%50==Math.floorMod(pos.asLong(),50))SanctuaryContent.sound(w,pos,be.spring?be.pool>=0&&!active?"spring_tainted":be.pool>=0?"spring_channel":"spring_ambient":"fire_ambient");
 }
 @Override protected void saveAdditional(CompoundTag n,HolderLookup.Provider r){super.saveAdditional(n,r);if(instance!=null)n.putUUID("Instance",instance);n.putLong("Origin",origin.asLong());n.putString("Rotation",rotation.name());n.putBoolean("Spring",spring);n.putInt("Pool",pool);n.putLong("RitualAt",ritualAt);}
 @Override protected void loadAdditional(CompoundTag n,HolderLookup.Provider r){super.loadAdditional(n,r);instance=n.hasUUID("Instance")?n.getUUID("Instance"):null;origin=BlockPos.of(n.getLong("Origin"));try{rotation=Rotation.valueOf(n.getString("Rotation"));}catch(IllegalArgumentException bad){rotation=Rotation.NONE;}spring=n.getBoolean("Spring");pool=n.contains("Pool")?n.getInt("Pool"):-1;ritualAt=n.contains("RitualAt")?n.getLong("RitualAt"):-100;}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider r){return saveWithoutMetadata(r);}
 @Override public net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket getUpdatePacket(){return net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket.create(this);}
}
